-- GUARDIAN NEXUS — 15-table schema
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, chat_id TEXT NOT NULL, chat_url TEXT NOT NULL, provider TEXT NOT NULL, account TEXT, name TEXT, token_total INTEGER DEFAULT 0, started_ts INTEGER NOT NULL, updated_ts INTEGER NOT NULL, meta TEXT DEFAULT '{}');
CREATE INDEX IF NOT EXISTS idx_sessions_chat_id ON sessions(chat_id);
CREATE TABLE IF NOT EXISTS artifacts (id TEXT PRIMARY KEY, hash TEXT NOT NULL UNIQUE, name TEXT NOT NULL DEFAULT 'artifact', type TEXT NOT NULL DEFAULT 'code_block', lang TEXT, content TEXT NOT NULL, context TEXT, chat_url TEXT NOT NULL, chat_id TEXT NOT NULL, account TEXT, job_id TEXT, session_id TEXT, direction TEXT DEFAULT 'output', provider TEXT DEFAULT 'claude', seen_count INTEGER DEFAULT 1, ts INTEGER NOT NULL, last_seen INTEGER NOT NULL, tags TEXT DEFAULT '[]', meta TEXT DEFAULT '{}');
CREATE INDEX IF NOT EXISTS idx_artifacts_hash ON artifacts(hash);
CREATE TABLE IF NOT EXISTS gaps (id TEXT PRIMARY KEY, type TEXT NOT NULL, domain TEXT, reason TEXT, description TEXT, score REAL NOT NULL DEFAULT 0.5, status TEXT DEFAULT 'open', job_id TEXT, chat_id TEXT, session_id TEXT, account TEXT, provider TEXT, evidence TEXT DEFAULT '{}', opened_ts INTEGER NOT NULL, closed_ts INTEGER, meta TEXT DEFAULT '{}');
CREATE INDEX IF NOT EXISTS idx_gaps_type ON gaps(type);
CREATE TABLE IF NOT EXISTS ledger_entries (id TEXT PRIMARY KEY, ledger_type TEXT NOT NULL, category TEXT NOT NULL, msg TEXT NOT NULL, meta TEXT DEFAULT '{}', chat_url TEXT, account TEXT, job_id TEXT, ts INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS timeline_events (id TEXT PRIMARY KEY, channel TEXT NOT NULL, person_id TEXT, event_type TEXT NOT NULL, payload TEXT DEFAULT '{}', ts INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, provider TEXT NOT NULL, command TEXT, prompt TEXT, content TEXT, status TEXT DEFAULT 'pending', response TEXT, error TEXT, ts INTEGER NOT NULL, updated_ts INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS downloads (id TEXT PRIMARY KEY, filename TEXT NOT NULL, href TEXT, chat_url TEXT, chat_id TEXT, account TEXT, job_id TEXT, ts INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pa_sessions (id TEXT PRIMARY KEY, job_id TEXT, chat_id TEXT, tokens INTEGER DEFAULT 0, pauses INTEGER DEFAULT 0, entropy TEXT DEFAULT '[]', hypotheses TEXT DEFAULT '[]', ts INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_ts INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS gap_questions (id TEXT PRIMARY KEY, gap_uuid TEXT NOT NULL, gap_type TEXT NOT NULL, gap_severity TEXT DEFAULT 'medium', subject TEXT NOT NULL, question TEXT NOT NULL, context_block TEXT NOT NULL, priority TEXT DEFAULT 'medium', hint TEXT, status TEXT DEFAULT 'pending', injected_at INTEGER, answer TEXT, answered_at INTEGER, resolved_at INTEGER, source TEXT, caused_by TEXT NOT NULL, ts INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_gapq_status ON gap_questions(status);
CREATE TABLE IF NOT EXISTS chat_sessions (id TEXT PRIMARY KEY, session_uuid TEXT NOT NULL, provider TEXT NOT NULL, instance_id TEXT NOT NULL, started_at INTEGER NOT NULL, ended_at INTEGER, source TEXT, caused_by TEXT);
CREATE TABLE IF NOT EXISTS chat_messages (id TEXT PRIMARY KEY, session_uuid TEXT NOT NULL, role TEXT NOT NULL, text TEXT NOT NULL, provider TEXT NOT NULL, complete INTEGER DEFAULT 0, ts INTEGER NOT NULL, source TEXT, caused_by TEXT);
CREATE TABLE IF NOT EXISTS chat_completions (id TEXT PRIMARY KEY, session_uuid TEXT NOT NULL, text TEXT NOT NULL, provider TEXT NOT NULL, complete INTEGER DEFAULT 1, caused_by_callto TEXT, ts INTEGER NOT NULL, caused_by TEXT);
CREATE TABLE IF NOT EXISTS guardian_nodes (id TEXT PRIMARY KEY, instance_id TEXT NOT NULL UNIQUE, last_seen INTEGER NOT NULL, capabilities TEXT DEFAULT '[]', tab_count INTEGER DEFAULT 0, listener_count INTEGER DEFAULT 0, health_score REAL DEFAULT 1.0);
CREATE TABLE IF NOT EXISTS guardian_health (id TEXT PRIMARY KEY, connected INTEGER NOT NULL, listener_count INTEGER DEFAULT 0, session_count INTEGER DEFAULT 0, stale_nodes TEXT DEFAULT '[]', lost_listeners INTEGER DEFAULT 0, health_score REAL NOT NULL, ts INTEGER NOT NULL);
